''', '''/**
 * Statuses that occupy a seat. A suspended member is locked out but keeps
 * their seat until they are removed; a pending `invited` row never held one.
 * The usage rollup counts with the same list, so the two cannot disagree.
 */
export const SEAT_HOLDING_STATUSES: readonly MemberStatus[] = [
  "active",
  "suspended",
];

/**
 * The seat count every plan check compares against: every live member who
 * holds a seat, suspended ones included. Only removal frees a seat.
 */
export async function countActiveMembers(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        inArray(members.status, [...SEAT_HOLDING_STATUSES]),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/**
 * How many live owners other than `exceptMemberId` are not suspended — the
 * owners who can still act for the workspace if that member steps away.
 */
export async function countUnsuspendedOwners(
  orgId: OrgId,
  exceptMemberId: MemberId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.role, "owner"),
        ne(members.status, "suspended"),
        ne(members.id, exceptMemberId),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/** The users currently suspended in this org; removed members are not among them. */
export async function listSuspendedUserIds(
  orgId: OrgId,
): Promise<readonly UserId[]> {
  const rows = getDb()
    .select({ userId: members.userId })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "suspended"),
        liveMemberPredicate(),
      ),
    )
    .all();
  return rows.map((row) => row.userId as UserId);
}
''')
