 * Suspends (`suspended`) or reinstates (`active`) a live member. Role, seat
 * and every other column are left alone; a removed row is never touched.
 */
export async function setMemberStatus(
  orgId: OrgId,
  memberId: MemberId,
  status: MemberStatus,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({ status, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.id, memberId),
        liveMemberPredicate(),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

/** Removal is a soft delete so the audit log keeps pointing at a real row. */''')

