export async function reinstateMember(
  actor: Actor,
  input: MemberStandingInput,
): Promise<Member> {
  const member = await loadMemberForStandingChange(actor, input, "reinstate");

  if (member.status !== "suspended") return member;

  const reinstated = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
