/**
 * Suspending and reinstating members, and everything a suspension switches
 * off: acting, notifications, the digest, assignments and mentions — while the
 * seat stays taken.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { NotFoundError } from "@/server/services/_support";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import * as commentService from "@/server/services/comment-service";
import { buildDigest, listDigestRecipients } from "@/server/services/digest-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { notify } from "@/server/services/notification-service";
import {
  getOrganizationSummary,
  listOrganizationsForUser,
} from "@/server/services/organization-service";
import { activityActionSchema } from "@/schemas/activity";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { MemberId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Member, Role } from "@/types/member";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

async function memberOf(tenant: Tenant, role: Role): Promise<Member> {
  const member = await memberRepo.findMember(tenant.org.id, tenant.userIds[role]);
  if (!member) throw new Error(`fixture ${role} missing`);
  return member;
}

async function suspend(tenant: Tenant, role: Role): Promise<Member> {
  const target = await memberOf(tenant, role);
  return memberService.suspendMember(tenant.actors.owner, {
    orgId: tenant.org.id,
    memberId: target.id,
  });
}

async function reinstate(tenant: Tenant, role: Role): Promise<Member> {
  const target = await memberOf(tenant, role);
  return memberService.reinstateMember(tenant.actors.owner, {
    orgId: tenant.org.id,
    memberId: target.id,
  });
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("suspendMember / reinstateMember", () => {
  it("suspends and reinstates, publishing one event each", async () => {
    const tenant = await createTenant("suspend-basic");
    const target = await memberOf(tenant, "member");
    const suspendedEvents = capture("member.suspended");
    const reinstatedEvents = capture("member.reinstated");

    const suspended = await suspend(tenant, "member");
    expect(suspended).toMatchObject({
      id: target.id,
      status: "suspended",
      role: "member",
      archivedAt: null,
    });
    expect(suspendedEvents).toHaveLength(1);
    expect(suspendedEvents[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      memberId: target.id,
      userId: tenant.userIds.member,
    });

    const reinstated = await reinstate(tenant, "member");
    expect(reinstated.status).toBe("active");
    expect(reinstatedEvents).toHaveLength(1);
    expect(reinstatedEvents[0]).toMatchObject({
      actorId: tenant.userIds.owner,
      memberId: target.id,
      userId: tenant.userIds.member,
    });
  });

  it("is a silent no-op when the member is already in that state", async () => {
    const tenant = await createTenant("suspend-noop");
    await suspend(tenant, "member");

    const suspendedEvents = capture("member.suspended");
    const again = await suspend(tenant, "member");
    expect(again.status).toBe("suspended");
    expect(suspendedEvents).toHaveLength(0);

    const reinstatedEvents = capture("member.reinstated");
    const active = await reinstate(tenant, "viewer");
    expect(active.status).toBe("active");
    expect(reinstatedEvents).toHaveLength(0);
  });

  it("applies the scope, not-found and permission guards", async () => {
    const tenant = await createTenant("suspend-guards");
    const other = await createTenant("suspend-guards-other");
    const viewer = await memberOf(tenant, "viewer");
    const foreign = await memberOf(other, "viewer");

    await expect(
      memberService.suspendMember(tenant.actors.owner, {
        orgId: other.org.id,
        memberId: foreign.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: foreign.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      memberService.reinstateMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: "missing" as MemberId,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      memberService.suspendMember(tenant.actors.member, {
        orgId: tenant.org.id,
        memberId: viewer.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    expect((await memberOf(tenant, "viewer")).status).toBe("active");
  });

  it("treats a removed member as not found, and never as suspended", async () => {
    const tenant = await createTenant("suspend-removed");
    const viewer = await memberOf(tenant, "viewer");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });

    for (const call of [memberService.suspendMember, memberService.reinstateMember]) {
      await expect(
        call(tenant.actors.owner, { orgId: tenant.org.id, memberId: viewer.id }),
      ).rejects.toBeInstanceOf(NotFoundError);
    }

    // Removal frees the seat and leaves no suspension behind.
    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(3);
    await expect(memberRepo.listSuspendedUserIds(tenant.org.id)).resolves.toEqual([]);
  });

  it("refuses self-suspension and suspending someone who outranks the actor", async () => {
    const tenant = await createTenant("suspend-rank");
    const owner = await memberOf(tenant, "owner");
    const admin = await memberOf(tenant, "admin");
    const events = capture("member.suspended");

    await expect(
      memberService.suspendMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        memberId: admin.id,
      }),
    ).rejects.toThrow();
    await expect(
      memberService.suspendMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        memberId: owner.id,
      }),
    ).rejects.toThrow();

    expect(events).toHaveLength(0);
    expect((await memberOf(tenant, "owner")).status).toBe("active");
    expect((await memberOf(tenant, "admin")).status).toBe("active");

    // An owner can suspend an admin; a suspended admin cannot reinstate themselves.
    await suspend(tenant, "admin");
    await expect(
      memberService.reinstateMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        memberId: admin.id,
      }),
    ).rejects.toThrow();
    expect((await memberOf(tenant, "admin")).status).toBe("suspended");
  });

  it("only counts unsuspended owners towards the last-owner rule", async () => {
    const tenant = await createTenant("suspend-owners");
    const owner = await memberOf(tenant, "owner");
    const admin = await memberOf(tenant, "admin");

    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
      role: "owner",
    });
    await suspend(tenant, "admin");

    // The second owner is suspended, so the first is the last one standing.
    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: owner.id,
        role: "admin",
      }),
    ).rejects.toThrow(/at least one owner/);
    await expect(
      memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: owner.id,
      }),
    ).rejects.toThrow(/at least one owner/);

    // Suspending the only unsuspended owner is refused, whoever asks.
    const events = capture("member.suspended");
    await expect(
      memberService.suspendMember(
        { userId: tenant.userIds.admin, orgId: tenant.org.id, role: "owner" },
        { orgId: tenant.org.id, memberId: owner.id },
      ),
    ).rejects.toThrow(/at least one owner/);
    expect(events).toHaveLength(0);
    expect((await memberOf(tenant, "owner")).status).toBe("active");

    // Once reinstated the second owner keeps the workspace ownable again.
    await reinstate(tenant, "admin");
    const demoted = await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: owner.id,
      role: "admin",
    });
    expect(demoted.role).toBe("admin");
  });

  it("records both actions in the audit log", async () => {
    const tenant = await createTenant("suspend-audit");
    const target = await memberOf(tenant, "member");
    detachers.push(registerActivityListeners());

    await suspend(tenant, "member");
    await reinstate(tenant, "member");

    for (const action of ["member.suspended", "member.reinstated"] as const) {
      expect(activityActionSchema.parse(action)).toBe(action);
      const page = await listActivity(tenant.actors.owner, {
        orgId: tenant.org.id,
        action: [action],
        limit: 25,
        cursor: null,
      });
      expect(page.items).toHaveLength(1);
      expect(page.items[0]).toMatchObject({
        action,
        actorId: tenant.userIds.owner,
        subjectKind: "member",
        subjectId: target.id,
      });
    }
  });
});

describe("while a member is suspended", () => {
  it("resolves no actor and drops the workspace from the org switcher", async () => {
    const tenant = await createTenant("suspend-actor");
    await suspend(tenant, "member");

    await expect(
      memberService.resolveActor(tenant.userIds.member, tenant.org.id),
    ).resolves.toBeNull();
    await expect(listOrganizationsForUser(tenant.userIds.member)).resolves.toEqual([]);

    await reinstate(tenant, "member");

    await expect(
      memberService.resolveActor(tenant.userIds.member, tenant.org.id),
    ).resolves.toMatchObject({ role: "member" });
    const orgs = await listOrganizationsForUser(tenant.userIds.member);
    expect(orgs.map((org) => org.id)).toEqual([tenant.org.id]);
  });

  it("keeps the seat in every count, and still lists the member", async () => {
    const tenant = await createTenant("suspend-seats");
    await usageRepo.recomputeUsage(tenant.org.id);
    await suspend(tenant, "member");

    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(4);
    expect((await usageRepo.getUsage(tenant.org.id)).seatsUsed).toBe(4);
    expect((await usageRepo.recomputeUsage(tenant.org.id)).seatsUsed).toBe(4);
    const summary = await getOrganizationSummary(tenant.actors.owner, tenant.org.id);
    expect(summary.memberCount).toBe(4);

    const page = await memberService.listMembers(tenant.actors.owner, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    const listed = page.items.find((row) => row.userId === tenant.userIds.member);
    expect(listed?.status).toBe("suspended");
    expect(page.items).toHaveLength(4);
  });

  it("creates no notifications and skips the digest until reinstated", async () => {
    const tenant = await createTenant("suspend-notify");
    const payload = { title: "t", body: "b", href: "/x", actorId: null };
    const now = Date.now();
    const windowStart = toIsoTimestamp(new Date(now - 3_600_000));
    const windowEnd = () => toIsoTimestamp(new Date(Date.now() + 1_000));

    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      kind: "comment_created",
      inApp: true,
      email: false,
      digestOnly: true,
    });
    const before = await notify(tenant.org.id, "comment_created", [tenant.userIds.member], payload);
    expect(before).toHaveLength(1);

    await suspend(tenant, "member");

    const during = await notify(
      tenant.org.id,
      "issue_assigned",
      [tenant.userIds.member, tenant.userIds.viewer],
      payload,
    );
    expect(during.map((row) => row.recipientId)).toEqual([tenant.userIds.viewer]);

    await expect(listDigestRecipients(tenant.org.id)).resolves.toEqual([]);
    await expect(
      buildDigest(tenant.org.id, tenant.userIds.member, windowStart, windowEnd()),
    ).resolves.toBeNull();

    // What they already had is untouched, and is digested after reinstatement.
    const unread = await notificationRepo.listUnreadSince(
      tenant.org.id,
      tenant.userIds.member,
      windowStart,
    );
    expect(unread).toHaveLength(1);

    await reinstate(tenant, "member");

    await expect(listDigestRecipients(tenant.org.id)).resolves.toEqual([tenant.userIds.member]);
    const bundle = await buildDigest(
      tenant.org.id,
      tenant.userIds.member,
      windowStart,
      windowEnd(),
    );
    expect(bundle?.entries).toHaveLength(1);
    const after = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.member], payload);
    expect(after).toHaveLength(1);
  });

  it("refuses new assignments but leaves existing ones alone", async () => {
    const tenant = await createTenant("suspend-assign");
    const held = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Already theirs",
        assigneeId: tenant.userIds.member,
      }),
    );
    const open = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Up for grabs" }),
    );

    await suspend(tenant, "member");
    const created = capture("issue.created");
    const assigned = capture("issue.assigned");

    await expect(
      issueService.createIssue(
        tenant.actors.owner,
        issueInput(tenant.org.id, tenant.project.id, {
          title: "Not for them",
          assigneeId: tenant.userIds.member,
        }),
      ),
    ).rejects.toBeInstanceOf(memberService.MemberSuspendedError);
    await expect(
      issueService.assignIssue(tenant.actors.owner, {
        orgId: tenant.org.id,
        issueId: open.id,
        assigneeId: tenant.userIds.member,
      }),
    ).rejects.toMatchObject({ code: "conflict" });

    expect(created).toHaveLength(0);
    expect(assigned).toHaveLength(0);
    const page = await issueService.listIssues(tenant.actors.owner, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(page.items.map((row) => row.title).sort()).toEqual(["Already theirs", "Up for grabs"]);
    expect(page.items.find((row) => row.id === held.id)?.assigneeId).toBe(tenant.userIds.member);
    expect(page.items.find((row) => row.id === open.id)?.assigneeId).toBeNull();

    // Assigning to an active member and un-assigning still work.
    const toViewer = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: open.id,
      assigneeId: tenant.userIds.viewer,
    });
    expect(toViewer.assigneeId).toBe(tenant.userIds.viewer);
    const unassigned = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: held.id,
      assigneeId: null,
    });
    expect(unassigned.assigneeId).toBeNull();

    await reinstate(tenant, "member");
    const back = await issueService.assignIssue(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: held.id,
      assigneeId: tenant.userIds.member,
    });
    expect(back.assigneeId).toBe(tenant.userIds.member);
  });

  it("cannot be mentioned by handle or by a client-supplied id", async () => {
    const tenant = await createTenant("suspend-mention");
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mention target" }),
    );
    await suspend(tenant, "member");
    const events = capture("comment.created");

    const comment = await commentService.createComment(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "cc @member and @admin",
      parentId: null,
      mentionedUserIds: [tenant.userIds.member, tenant.userIds.viewer],
    });

    const expected = [tenant.userIds.admin, tenant.userIds.viewer];
    expect([...comment.mentionedUserIds].sort()).toEqual([...expected].sort());
    expect([...(events[0]?.mentionedUserIds ?? [])].sort()).toEqual([...expected].sort());

    await reinstate(tenant, "member");
    const later = await commentService.createComment(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "cc @member",
      parentId: null,
      mentionedUserIds: [],
    });
    expect(later.mentionedUserIds).toEqual([tenant.userIds.member]);
  });
});

